"""`bn new-adapter` — scaffold a tested adapter package in one command.

    bn new-adapter lab my_robot --dir adapters-contrib
    bn new-adapter tool my_docking --dir adapters-contrib

Generates a ready-to-run module + pytest file implementing the chosen
interface, following docs/ADAPTERS.md rules.
"""
from __future__ import annotations

import argparse
import re
from pathlib import Path

TEMPLATES: dict[str, dict[str, str]] = {
    "lab": {
        "module": '''"""{name_human} — LabAdapter (IAL contract). Generated by bn new-adapter.

Rules (docs/ADAPTERS.md): agents reach this ONLY through LabGateway; declare
exactly the capabilities you implement; never perform unsafe actions here.
"""
from __future__ import annotations

from typing import Any

from bionexus.core.contracts import (
    AssayResult, Envelope, InstrumentInfo, ProtocolSubmission, RunStatus,
)


class {class_name}:
    name = "{snake_name}"

    def __init__(self, seed: int = 0):
        self.seed = seed
        self._runs: dict[str, ProtocolSubmission] = {{}}

    def list_capabilities(self) -> dict[str, Any]:
        # TODO: declare your instrument's real capabilities
        return {{"assays": ["binding"], "throughput": {{"plates_per_day": 8}}, "bsl_max": 1}}

    def submit_protocol(self, protocol: ProtocolSubmission) -> str:
        # TODO: compile protocol to your instrument's script and enqueue it
        run_id = f"{{self.name}}-{{protocol.protocol_id[:8]}}"
        self._runs[run_id] = protocol
        return run_id

    def get_status(self, run_id: str) -> str:
        return "done" if run_id in self._runs else "failed"

    def fetch_results(self, run_id: str) -> AssayResult:
        # TODO: normalize your instrument's raw output into the AssayResult contract
        protocol = self._runs[run_id]
        return AssayResult(
            envelope=Envelope(experiment_branch_id=self.name),
            protocol_id=protocol.protocol_id,
            instrument=InstrumentInfo(adapter=self.name, instrument_id="{snake_name}-01"),
            status=RunStatus.completed,
            measurements=[],  # TODO
        )

    def cancel(self, run_id: str) -> None:
        self._runs.pop(run_id, None)
''',
        "test": '''import pytest

from bionexus.core.contracts import (
    Envelope, ProtocolOp, ProtocolStep, ProtocolSubmission,
    ReagentSpec, SampleKind, SampleSpec,
)
from bionexus.core.safety import LabGateway, SafetyEngine
from bionexus.adapters.store.sqlite import SqliteProvenanceStore
from bionexus.core.interfaces import system_actor
from {module_name} import {class_name}


def make_protocol():
    return ProtocolSubmission(
        envelope=Envelope(experiment_branch_id="test"),
        title="smoke", assay_type="binding",
        steps=[ProtocolStep(seq=1, op=ProtocolOp.dispense, params={{"volume_ul": 10}})],
        samples=[SampleSpec(sample_id="C1", kind=SampleKind.compound, concentration="10uM")],
        reagents=[ReagentSpec(name="buffer", amount="1 mL", bsl_level=1)],
    )


def test_adapter_contract():
    store = SqliteProvenanceStore()
    gateway = LabGateway({class_name}(), SafetyEngine(), store, system_actor())
    run_id, rejection = gateway.submit(make_protocol())
    assert rejection is None and run_id
    assert gateway.lab.get_status(run_id) == "done"
    result = gateway.results(Envelope(experiment_branch_id="test"), run_id)
    assert result.instrument.adapter == "{snake_name}"
''',
    },
    "tool": {
        "module": '''"""{name_human} — BioTool. Generated by bn new-adapter.

BioTools are pure computation: no physical actions, no network required.
"""
from __future__ import annotations

from typing import Any

from bionexus.core.contracts import ToolInvocation, ToolName, ToolResult


class {class_name}:
    name = "{snake_name}"
    capabilities = (ToolName("{cap}"),)

    def invoke(self, invocation: ToolInvocation) -> ToolResult:
        try:
            output = self._compute(invocation.args)
        except Exception as exc:  # narrow this for production use
            return ToolResult(envelope=invocation.envelope.model_copy(),
                              invocation_id=invocation.invocation_id,
                              status="failed", rejection_reason=str(exc))
        return ToolResult(envelope=invocation.envelope.model_copy(),
                          invocation_id=invocation.invocation_id,
                          status="succeeded", output=output)

    def _compute(self, args: dict[str, Any]) -> dict[str, Any]:
        # TODO: your computation here
        return {{"echo": args}}
''',
        "test": '''from bionexus.core.contracts import Envelope, ToolInvocation
from {module_name} import {class_name}


def test_tool_contract():
    tool = {class_name}()
    inv = ToolInvocation(envelope=Envelope(experiment_branch_id="test"),
                         tool="{cap}", args={{"hello": "world"}})
    result = tool.invoke(inv)
    assert result.status == "succeeded"
    assert result.output["echo"]["hello"] == "world"
''',
    },
}

TOOL_CAP_CHOICES = ["c.fm.predict_property", "c.evals.benchmark_batch",
                    "e.sim.docking", "c.kb.search_literature"]


def snake(name: str) -> str:
    s = re.sub(r"(?<!^)(?=[A-Z])", "_", name).lower()
    return re.sub(r"[^a-z0-9_]", "_", s)


def scaffold(kind: str, name: str, out_dir: Path, cap: str | None = None) -> Path:
    if kind not in TEMPLATES:
        raise SystemExit(f"unknown adapter kind '{kind}' (choose: {', '.join(TEMPLATES)})")
    class_name = "".join(p.capitalize() for p in snake(name).split("_"))
    module_name = name if "." not in name else name.rsplit(".", 1)[-1]
    if kind == "tool":
        if cap is None:
            cap = TOOL_CAP_CHOICES[0]
        if not cap.startswith("c.") and not cap.startswith("e."):
            raise SystemExit("tool capability must be a registered ToolName (see contracts)")
    t = TEMPLATES[kind]
    fmt = dict(name_human=name.replace("_", " ").replace("-", " "),
               class_name=class_name, snake_name=snake(name),
               module_name=f"{module_name}_adapter", cap=cap or "")
    target = out_dir / f"{snake(name)}_adapter"
    target.mkdir(parents=True, exist_ok=True)
    (target / f"{snake(name)}_adapter.py").write_text(t["module"].format(**fmt))
    (target / f"test_{snake(name)}_adapter.py").write_text(t["test"].format(**fmt))
    return target


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="bn new-adapter")
    parser.add_argument("kind", choices=sorted(TEMPLATES), help="adapter interface")
    parser.add_argument("name", help="adapter name, e.g. my_robot")
    parser.add_argument("--dir", default="adapters-contrib", help="output directory")
    parser.add_argument("--cap", default=None,
                        help=f"tool capability (tools only); e.g. {TOOL_CAP_CHOICES[0]}")
    args = parser.parse_args(argv)
    try:
        path = scaffold(args.kind, args.name, Path(args.dir), args.cap)
    except SystemExit as exc:
        print(exc)
        return 2
    print(f"scaffolded {args.kind} adapter: {path}")
    print(f"run tests:  .venv/bin/python -m pytest {path}")
    return 0


if __name__ == "__main__":  # pragma: no cover
    raise SystemExit(main())
